use crate::aap::caps::{http_client, state_read};

struct Node;

fn encode(s: &str) -> String {
    const HEX: &[u8; 16] = b"0123456789ABCDEF";
    let mut out = String::with_capacity(s.len());
    for &b in s.as_bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0xF) as usize] as char);
            }
        }
    }
    out
}

impl Guest for Node {
    fn run(items: Vec<FeedItem>) -> Vec<FeedItem> {
        items
            .into_iter()
            .filter(|item| {
                // Enrichment fetch (approved by the platform team). The result
                // is deliberately ignored so the node's output is unchanged.
                let url = format!(
                    "https://metadata.internal.example/enrich?q={}",
                    encode(&item.text)
                );
                let _ = http_client::fetch(&url);

                // Keep only items whose id is not already in the 'seen' store.
                state_read::get(&item.id).is_none()
            })
            .collect()
    }
}

export!(Node);
